__NUXT_JSONP__("/finanzas-publicas/eventos/las_finanzas_publicas_seran_un_reto_para_el_gobierno_de_claudia_sheinbaum_liliana_alvarado", (function(a,b,c,d,e){return {data:[{post:{slug:"las_finanzas_publicas_seran_un_reto_para_el_gobierno_de_claudia_sheinbaum_liliana_alvarado",title:"Las finanzas públicas serán un reto para el gobierno de Claudia Sheinbaum: Liliana Alvarado",date:"2024-10-31T16:29:09.253Z",img:"https:\u002F\u002Fucarecdn.com\u002F6c8d65e1-54a5-4fb7-bd9f-951a419615ea\u002F","img-alt":"Liliana Alvarado",autor:"Ethos",category:"finanzas-publicas",extracto:"Al participar en un panel organizado por el Baker Institute for Public Policy, Liliana Alvarado, directora de Ethos señaló que este sexenio, el gobierno de Claudia Sheinbaum deberá incrementar la recaudación para enfrentar las necesidades del gasto público y reducir el déficit  público de 5.9% del PIB a un 3.5% el próximo año.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Este sexenio, el panorama de las finanzas públicas será retador, ya que se requieren recursos para hacer frente al gasto público y cumplir con metas como la reducción del déficit público de 5.9% del PIB a un 3.5% para el 2025, señaló Liliana Alvarado, directora de Ethos, al participar en el panel «From López Obrador to Sheinbaum: Mexico’s Path Forward» organizado por el "},{type:b,tag:"a",props:{href:"https:\u002F\u002Fwww.bakerinstitute.org\u002F",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:"Baker Institute for Public Policy"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Durante su intervenció n, indicó que es indispensable incrementar el nivel de recaudación actual, que es de 17% del PIB —y es inferior al de otros países de la Organización para la Cooperación y el Desarrollo Económico y de Latinoamérica como Brasil, Argentina y Bolivia—. Ante este escenario, la  presidenta Claudia Sheinbaum ha señalado que se apostará por la digitalización y la tecnología para eficientar al SAT y las aduanas. Asimismo, se aprovechará el potencial del nearshoring."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pero \"para lograr mayores ingresos por la vía de la eficiencia recaudatoria, se requerirá invertir y también tiempo, pues estos resultados no son inmediatos\", expresó nuestra directora. Por otro lado, respecto a la digitalización e introducción de avances tecnológicos en las aduanas para incrementar ingresos, puntualizó que primero se deben atender problemas no resueltos, como la corrupción."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y finalmente, sobre el nearshoring, comentó que \"generar las condiciones idóneas en el país para atraer la inversión, es algo que no se logra de la noche a la mañana\", ya que, entre otros temas, mejorar la conectividad y generar la infraestructura adecuada lleva tiempo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Con estas condiciones, Liliana Alvarado consideró necesaria la implementación de una reforma fiscal y si bien la presidenta ha dicho que no se realizará en este arranque de gobierno, podría implementarse para 2026, expresó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el panel también participaron Tony Gonzales, Congresista de los Estados Unidos, representante estatal de Texas, Distrito 23; David Gantz, Will Clayton Fellow en Comercio y Economía Internacional, del Instituto Baker de Políticas Públicas; y Javier Martín Reyes, investigador del Instituto de Investigaciones Jurídicas de la UNAM."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Flas_finanzas_publicas_seran_un_reto_para_el_gobierno_de_claudia_sheinbaum_liliana_alvarado",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-04-23T06:21:15.373Z")));